  "scripts": {
    "build": "esbuild src/content.ts src/page-hook.ts src/background.ts --bundle --outdir=extension/dist --target=chrome111",
    "watch": "npm run build -- --watch",
    "typecheck": "tsc",
    "test": "node --test \"test/**/*.test.ts\"",
    "format": "prettier --write src test eval/check.ts extension/manifest.json",
    "check-claims": "node --env-file=.env eval/check.ts"
  },
  "devDependencies": {
    "@types/chrome": "^0.3.5",
    "@types/node": "^26.6.5",
import assert from "node:assert/strict";
import { test } from "node:test";
import { MODEL, reportSummary } from "../eval/model.ts";

test("the accuracy check runs on Haiku 5.5", () => {
  assert.equal(MODEL, "claude-haiku-5-5");
});

test("the report names the model and prices the run at Haiku rates", () => {
  // 1M input tokens ($0.10) + 1M output ($0.50) + 100 searches ($1.00).
  const usage = { input: 1_000_000, output: 1_000_000, searches: 100 };
  assert.equal(
    reportSummary(10, usage, []),
    "claude-haiku-5-5 · 10 claims · 100 searches · 0 failed searches (none) · about $1.60",
  );
});

